export function basicCalculator(expression        )         {
const s=expression.replace(/ /g,'');let i=0;function atom()       {let sign=1;while(s[i]==='+'||s[i]==='-'){if(s[i]==='-')sign=-sign;i++;}let value=0;if(s[i]==='('){i++;value=sum();i++;}else while(i<s.length&&/\d/.test(s[i]))value=value*10+Number(s[i++]);return sign*value;}function sum()       {let value=atom();while(i<s.length&&s[i]!==')'){const op=s[i++],x=atom();value+=op==='+'?x:-x;}return value;}return sum();
}

